-- Expands the CCP question bank to three full exams' worth, spread by the
-- official exam-guide domain weights. Answers stay server-only (no client SELECT policy).

insert into public.questions (
  cert_id, domain, prompt, choices, correct_choice_ids, explanation, difficulty, hint
) values
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa trocou a compra antecipada de servidores por pagamento mensal conforme o uso da AWS. Qual benefício da nuvem descreve essa mudança?', '[{"id": "a", "text": "Trocar despesas de capital (CAPEX) por despesas variáveis (OPEX)"}, {"id": "b", "text": "Aumentar a velocidade de rede entre datacenters próprios"}, {"id": "c", "text": "Garantir licenças de software gratuitas para sempre"}, {"id": "d", "text": "Eliminar a necessidade de qualquer controle de segurança"}]'::jsonb, array['a'], 'Na nuvem a empresa deixa de investir antecipadamente em hardware (CAPEX) e passa a pagar apenas pelo que consome (OPEX), alinhando custo e demanda real.', 'easy', 'Pense em quando o dinheiro sai do caixa: antes ou conforme o uso.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma loja virtual dimensionava servidores para a Black Friday e os deixava ociosos o resto do ano. Qual benefício da AWS resolve esse desperdício?', '[{"id": "a", "text": "Assinar contratos de 10 anos com a AWS"}, {"id": "b", "text": "Usar somente instâncias com GPU"}, {"id": "c", "text": "Manter um datacenter de contingência próprio"}, {"id": "d", "text": "Parar de adivinhar a capacidade necessária"}]'::jsonb, array['d'], 'Na AWS é possível aumentar e reduzir recursos conforme a demanda real, em vez de comprar capacidade para o pico e pagar por ela o ano inteiro.', 'easy', 'O problema é prever o pico com antecedência.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual pilar do AWS Well-Architected Framework trata de executar e monitorar sistemas e de melhorar continuamente processos e procedimentos?', '[{"id": "a", "text": "Eficiência de performance"}, {"id": "b", "text": "Otimização de custos"}, {"id": "c", "text": "Excelência operacional"}, {"id": "d", "text": "Sustentabilidade"}]'::jsonb, array['c'], 'Excelência operacional cobre operações como código, mudanças pequenas e frequentes, aprendizado com falhas e melhoria contínua de procedimentos.', 'medium', 'O foco é a forma de operar e evoluir os processos.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual pilar do Well-Architected Framework enfatiza a capacidade de uma carga de trabalho se recuperar de falhas e atender à demanda de forma consistente?', '[{"id": "a", "text": "Segurança"}, {"id": "b", "text": "Confiabilidade"}, {"id": "c", "text": "Otimização de custos"}, {"id": "d", "text": "Excelência operacional"}]'::jsonb, array['b'], 'Confiabilidade trata de recuperação automática de falhas, testes de recuperação, escala horizontal e gestão de mudanças para que o sistema funcione como esperado.', 'medium', 'Recuperação de falhas é a palavra-chave.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma equipe escolhe tipos de instância e serviços de armazenamento adequados ao perfil de carga e revisa essas escolhas conforme surgem novas tecnologias. Qual pilar do Well-Architected está sendo aplicado?', '[{"id": "a", "text": "Excelência operacional"}, {"id": "b", "text": "Segurança"}, {"id": "c", "text": "Confiabilidade"}, {"id": "d", "text": "Eficiência de performance"}]'::jsonb, array['d'], 'Eficiência de performance é sobre usar recursos computacionais de forma eficiente, escolhendo os tipos certos e evoluindo com a tecnologia.', 'medium', 'A questão fala em usar os recursos certos para o desempenho.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa migra uma aplicação para a AWS trocando o banco autogerenciado no servidor pelo Amazon RDS, sem alterar a arquitetura principal. Qual estratégia de migração é essa?', '[{"id": "a", "text": "Retire"}, {"id": "b", "text": "Replatform (lift, tinker and shift)"}, {"id": "c", "text": "Repurchase"}, {"id": "d", "text": "Rehost (lift and shift)"}]'::jsonb, array['b'], 'Replatform faz pequenas otimizações durante a migração, como trocar o banco autogerenciado por um serviço gerenciado, sem reescrever a aplicação.', 'easy', 'Houve uma pequena otimização, mas não uma reescrita.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa vai reescrever um monólito como microsserviços serverless para ganhar agilidade e escala. Qual estratégia de migração descreve isso?', '[{"id": "a", "text": "Refactor / re-architect"}, {"id": "b", "text": "Relocate"}, {"id": "c", "text": "Retain"}, {"id": "d", "text": "Rehost"}]'::jsonb, array['a'], 'Refactor (re-architect) muda a arquitetura da aplicação para aproveitar recursos nativos de nuvem, como serverless e microsserviços.', 'medium', 'A aplicação muda de arquitetura.'),
  ('ccp', 'Conceitos de Nuvem', 'Durante a avaliação de migração, uma empresa descobre aplicações que ninguém usa mais. Qual estratégia de migração se aplica a elas?', '[{"id": "a", "text": "Retain"}, {"id": "b", "text": "Retire"}, {"id": "c", "text": "Rehost"}, {"id": "d", "text": "Repurchase"}]'::jsonb, array['b'], 'Retire significa desligar o que não tem mais valor. Isso reduz custo e o escopo da migração.', 'easy', 'O que fazer com algo que ninguém usa?'),
  ('ccp', 'Conceitos de Nuvem', 'Um sistema legado precisa continuar no datacenter por mais dois anos por exigência regulatória antes de qualquer decisão. Qual estratégia de migração representa essa escolha?', '[{"id": "a", "text": "Retire"}, {"id": "b", "text": "Rehost"}, {"id": "c", "text": "Retain (manter)"}, {"id": "d", "text": "Refactor"}]'::jsonb, array['c'], 'Retain mantém a aplicação onde está por enquanto, para revisitar a decisão no futuro.', 'medium', 'Nada vai mudar agora.'),
  ('ccp', 'Conceitos de Nuvem', 'Quais perspectivas pertencem ao conjunto de capacidades de NEGÓCIO do AWS Cloud Adoption Framework (AWS CAF)? (Escolha DUAS)', '[{"id": "a", "text": "Segurança (Security)"}, {"id": "b", "text": "Plataforma (Platform)"}, {"id": "c", "text": "Governança (Governance)"}, {"id": "d", "text": "Negócios (Business)"}, {"id": "e", "text": "Operações (Operations)"}]'::jsonb, array['c', 'd'], 'O AWS CAF tem seis perspectivas. Negócios, Pessoas e Governança focam em capacidades de negócio; Plataforma, Segurança e Operações focam em capacidades técnicas.', 'medium', 'Separe o que é técnico do que é organizacional.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual perspectiva do AWS CAF trata de cultura organizacional, gestão de mudanças, liderança e desenvolvimento de habilidades em nuvem?', '[{"id": "a", "text": "Plataforma (Platform)"}, {"id": "b", "text": "Operações (Operations)"}, {"id": "c", "text": "Segurança (Security)"}, {"id": "d", "text": "Pessoas (People)"}]'::jsonb, array['d'], 'A perspectiva Pessoas ajuda a evoluir cultura, estrutura organizacional, liderança e capacitação das equipes para a nuvem.', 'medium', 'O assunto são as pessoas e a organização.'),
  ('ccp', 'Conceitos de Nuvem', 'O que significa dizer que a AWS oferece economia de escala?', '[{"id": "a", "text": "O cliente precisa comprar capacidade em grandes lotes"}, {"id": "b", "text": "Cada cliente recebe um datacenter exclusivo"}, {"id": "c", "text": "O uso agregado de milhares de clientes permite à AWS operar com custos menores e repassar preços mais baixos"}, {"id": "d", "text": "Os preços aumentam conforme mais clientes entram"}]'::jsonb, array['c'], 'Como a AWS atende muitos clientes, ela compra e opera infraestrutura em escala enorme, reduzindo custos unitários e diminuindo preços ao longo do tempo.', 'easy', 'Pense no efeito de comprar em volume gigantesco.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma aplicação precisa atender usuários de uma cidade com latência de um dígito em milissegundos, mais perto do que a Região mais próxima permite. Qual infraestrutura da AWS atende melhor?', '[{"id": "a", "text": "AWS Direct Connect sem nenhum outro serviço"}, {"id": "b", "text": "AWS Local Zones"}, {"id": "c", "text": "Uma nova conta AWS"}, {"id": "d", "text": "Amazon CloudFront somente para APIs dinâmicas"}]'::jsonb, array['b'], 'Local Zones colocam computação, armazenamento e banco de dados perto de grandes centros populacionais para cargas sensíveis à latência.', 'medium', 'Procure uma extensão de Região mais próxima dos usuários.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma operadora quer executar aplicações de latência ultrabaixa para dispositivos 5G dentro da própria rede da operadora. Qual oferta da AWS foi criada para isso?', '[{"id": "a", "text": "AWS Wavelength"}, {"id": "b", "text": "AWS Snowball Edge"}, {"id": "c", "text": "Amazon Lightsail"}, {"id": "d", "text": "AWS Outposts"}]'::jsonb, array['a'], 'Wavelength incorpora computação e armazenamento AWS nos datacenters das operadoras 5G, reduzindo a latência para dispositivos móveis.', 'medium', 'A palavra-chave é 5G.'),
  ('ccp', 'Conceitos de Nuvem', 'O que são os pontos de presença (edge locations) da AWS?', '[{"id": "a", "text": "Escritórios de suporte técnico da AWS"}, {"id": "b", "text": "Zonas de Disponibilidade reservadas para bancos de dados"}, {"id": "c", "text": "Locais usados por serviços como CloudFront e Route 53 para entregar conteúdo e respostas mais perto dos usuários"}, {"id": "d", "text": "Datacenters onde o cliente pode alugar racks físicos"}]'::jsonb, array['c'], 'Edge locations ficam espalhados pelo mundo e reduzem a latência de serviços como CloudFront, Route 53 e Global Accelerator.', 'easy', 'Eles ficam na borda, perto do usuário final.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma aplicação crítica precisa continuar disponível mesmo que uma Região AWS inteira fique indisponível. Qual arquitetura atende esse requisito?', '[{"id": "a", "text": "Implantar a aplicação em mais de uma Região, com replicação de dados e failover"}, {"id": "b", "text": "Aumentar o tamanho da instância"}, {"id": "c", "text": "Usar várias instâncias na mesma Zona de Disponibilidade"}, {"id": "d", "text": "Ativar o AWS Free Tier"}]'::jsonb, array['a'], 'Multi-AZ protege contra a perda de um datacenter, mas só uma arquitetura multi-Região protege contra a indisponibilidade de uma Região inteira.', 'medium', 'Qual escopo de falha precisa ser coberto?'),
  ('ccp', 'Conceitos de Nuvem', 'Qual princípio de design da nuvem recomenda que os componentes de uma aplicação se comuniquem por filas e eventos, para que a falha de um não derrube os outros?', '[{"id": "a", "text": "Concentrar tudo em um único servidor"}, {"id": "b", "text": "Desacoplar componentes (loose coupling)"}, {"id": "c", "text": "Escalar verticalmente sempre"}, {"id": "d", "text": "Evitar automação"}]'::jsonb, array['b'], 'Componentes desacoplados (por exemplo, com Amazon SQS ou Amazon EventBridge) toleram falhas e escalam de forma independente.', 'medium', 'Como evitar que uma parte dependa diretamente da outra?'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa troca uma instância grande por várias menores atrás de um load balancer, adicionando mais quando a demanda cresce. Que tipo de escalabilidade é essa?', '[{"id": "a", "text": "Escalabilidade manual de hardware físico"}, {"id": "b", "text": "Escalabilidade horizontal (scale out)"}, {"id": "c", "text": "Escalabilidade vertical (scale up)"}, {"id": "d", "text": "Escalabilidade diagonal"}]'::jsonb, array['b'], 'Escalar horizontalmente adiciona mais instâncias. Escalar verticalmente aumenta o tamanho de uma única instância.', 'easy', 'Mais máquinas ou máquina maior?'),
  ('ccp', 'Conceitos de Nuvem', 'Na nuvem, qual prática transforma a infraestrutura em algo que pode ser versionado, revisado e recriado de forma idêntica?', '[{"id": "a", "text": "Documentação em planilhas"}, {"id": "b", "text": "Configuração manual pelo console"}, {"id": "c", "text": "Infraestrutura como código (IaC)"}, {"id": "d", "text": "Compra de hardware padronizado"}]'::jsonb, array['c'], 'Com IaC (por exemplo, AWS CloudFormation) a infraestrutura é descrita em arquivos versionados, o que permite repetir ambientes e reduzir erros manuais.', 'medium', 'Pense em tratar a infraestrutura como software.'),
  ('ccp', 'Conceitos de Nuvem', 'Ao calcular o custo total de propriedade (TCO) de migrar para a AWS, quais custos de um datacenter próprio devem ser considerados? (Escolha DUAS)', '[{"id": "a", "text": "Energia, refrigeração e espaço físico"}, {"id": "b", "text": "O preço de domínios .com"}, {"id": "c", "text": "O valor das ações da AWS"}, {"id": "d", "text": "O número de usuários do Amazon Prime"}, {"id": "e", "text": "Mão de obra para manter servidores e hardware"}]'::jsonb, array['a', 'e'], 'O TCO compara todos os custos: hardware, energia, refrigeração, espaço, rede, licenças e a mão de obra que mantém a infraestrutura funcionando.', 'medium', 'Inclua custos indiretos, não só o servidor.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa já possui licenças de Microsoft SQL Server e quer usá-las na AWS para reduzir custos. Qual modelo de licenciamento é esse?', '[{"id": "a", "text": "Reserved Instances"}, {"id": "b", "text": "Licença incluída (license included)"}, {"id": "c", "text": "BYOL (Bring Your Own License)"}, {"id": "d", "text": "Free Tier"}]'::jsonb, array['c'], 'Com BYOL o cliente leva licenças elegíveis que já possui; no modelo license included, o custo da licença vem embutido no preço do serviço.', 'medium', 'A empresa já tem as licenças.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual é a principal vantagem de usar várias Zonas de Disponibilidade para uma aplicação?', '[{"id": "a", "text": "Obter suporte técnico gratuito"}, {"id": "b", "text": "Alta disponibilidade e tolerância a falhas caso um datacenter tenha problemas"}, {"id": "c", "text": "Eliminar a necessidade de backups"}, {"id": "d", "text": "Reduzir a fatura para zero"}]'::jsonb, array['b'], 'AZs são isoladas fisicamente e conectadas por rede de baixa latência. Distribuir a aplicação entre elas evita que uma falha local a derrube.', 'easy', 'O que acontece se um datacenter falhar?'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa precisa transferir 80 TB de dados para a AWS, mas a conexão de internet levaria meses. Qual serviço resolve com transporte físico?', '[{"id": "a", "text": "Amazon CloudFront"}, {"id": "b", "text": "AWS Direct Connect configurado na mesma semana"}, {"id": "c", "text": "Amazon S3 Glacier Deep Archive"}, {"id": "d", "text": "AWS Snowball Edge"}]'::jsonb, array['d'], 'Os dispositivos da família AWS Snow são enviados ao cliente, carregados localmente e devolvidos à AWS, o que é útil quando a rede seria lenta ou cara demais.', 'medium', 'Às vezes é mais rápido mandar o disco pelo correio.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual serviço automatiza a migração de servidores físicos e virtuais para Amazon EC2 com replicação contínua e mínimo tempo de inatividade (rehost)?', '[{"id": "a", "text": "AWS Artifact"}, {"id": "b", "text": "AWS Database Migration Service apenas"}, {"id": "c", "text": "Amazon Lightsail"}, {"id": "d", "text": "AWS Application Migration Service (AWS MGN)"}]'::jsonb, array['d'], 'O AWS MGN replica servidores de origem continuamente para a AWS e permite um corte rápido, sendo o serviço recomendado para lift-and-shift.', 'medium', 'O cenário é rehost de servidores.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa quer migrar um banco Oracle para Amazon Aurora PostgreSQL mantendo a origem em funcionamento durante a migração. Quais serviços ajudam? (Escolha DUAS)', '[{"id": "a", "text": "AWS Shield"}, {"id": "b", "text": "Amazon Inspector"}, {"id": "c", "text": "AWS Database Migration Service (AWS DMS)"}, {"id": "d", "text": "AWS Schema Conversion Tool (AWS SCT)"}, {"id": "e", "text": "Amazon Polly"}]'::jsonb, array['c', 'd'], 'O AWS DMS migra e replica os dados com a origem ativa; o AWS SCT converte schema e código quando o banco de destino é de outro mecanismo.', 'medium', 'Um serviço move dados; o outro converte a estrutura.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual afirmação descreve corretamente a elasticidade na nuvem?', '[{"id": "a", "text": "Contratar capacidade fixa para três anos"}, {"id": "b", "text": "Manter sempre a capacidade do pico máximo"}, {"id": "c", "text": "Adicionar e remover recursos automaticamente para acompanhar a demanda"}, {"id": "d", "text": "Usar apenas servidores físicos dedicados"}]'::jsonb, array['c'], 'Elasticidade é ajustar os recursos para cima e para baixo conforme a carga, pagando apenas pelo que é usado.', 'easy', 'Ela funciona nos dois sentidos.'),
  ('ccp', 'Conceitos de Nuvem', 'Qual pilar do Well-Architected recomenda implementar uma base de identidade forte, rastreabilidade e proteção de dados em trânsito e em repouso?', '[{"id": "a", "text": "Confiabilidade"}, {"id": "b", "text": "Eficiência de performance"}, {"id": "c", "text": "Segurança"}, {"id": "d", "text": "Sustentabilidade"}]'::jsonb, array['c'], 'O pilar Segurança inclui menor privilégio, rastreabilidade, segurança em todas as camadas e proteção de dados em trânsito e em repouso.', 'medium', 'Identidade e criptografia são temas de qual pilar?'),
  ('ccp', 'Conceitos de Nuvem', 'Qual ferramenta gratuita ajuda a revisar cargas de trabalho comparando-as com as boas práticas do Well-Architected Framework?', '[{"id": "a", "text": "AWS Pricing Calculator"}, {"id": "b", "text": "AWS Marketplace"}, {"id": "c", "text": "AWS Well-Architected Tool"}, {"id": "d", "text": "Amazon Inspector"}]'::jsonb, array['c'], 'A AWS Well-Architected Tool, no console, guia revisões por pilar e gera um plano de melhorias para a carga de trabalho.', 'easy', 'O nome da ferramenta é bem direto.'),
  ('ccp', 'Conceitos de Nuvem', 'Em qual modelo de serviço o cliente gerencia o sistema operacional, o runtime e a aplicação, enquanto o provedor cuida do hardware e da virtualização?', '[{"id": "a", "text": "Serverless puro, como o AWS Lambda"}, {"id": "b", "text": "IaaS, como o Amazon EC2"}, {"id": "c", "text": "SaaS, como um webmail"}, {"id": "d", "text": "PaaS totalmente gerenciado"}]'::jsonb, array['b'], 'Em IaaS o provedor oferece a infraestrutura virtualizada; sistema operacional, patches, runtime e aplicação ficam com o cliente.', 'medium', 'Quem aplica patches no sistema operacional?'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa quer reduzir custos sem perder desempenho. Qual combinação reflete princípios de otimização de custos do Well-Architected?', '[{"id": "a", "text": "Evitar medir gastos por equipe"}, {"id": "b", "text": "Superdimensionar tudo para nunca faltar capacidade"}, {"id": "c", "text": "Dimensionar corretamente os recursos e pagar apenas pelo que é usado"}, {"id": "d", "text": "Manter ambientes de teste ligados 24/7"}]'::jsonb, array['c'], 'Otimização de custos inclui medir gastos, dimensionar corretamente (rightsizing), adotar um modelo de consumo e eliminar recursos ociosos.', 'hard', 'Pague pelo necessário e meça os gastos.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma aplicação de streaming é executada em duas Regiões. Qual vantagem real esse desenho traz além da resiliência?', '[{"id": "a", "text": "Custo zero de transferência entre Regiões"}, {"id": "b", "text": "Dispensa de backups"}, {"id": "c", "text": "Menor latência para usuários próximos de cada Região"}, {"id": "d", "text": "Conformidade automática com qualquer lei"}]'::jsonb, array['c'], 'Atender usuários a partir da Região mais próxima reduz a latência. Transferência entre Regiões tem custo e a conformidade ainda depende do cliente.', 'hard', 'Pense em onde os usuários estão.'),
  ('ccp', 'Segurança e Conformidade', 'No modelo de responsabilidade compartilhada, quem é responsável pela segurança física dos datacenters onde os serviços AWS rodam?', '[{"id": "a", "text": "A responsabilidade é dividida igualmente entre AWS e cliente"}, {"id": "b", "text": "O parceiro que revende os serviços"}, {"id": "c", "text": "O cliente"}, {"id": "d", "text": "A AWS"}]'::jsonb, array['d'], 'A segurança DA nuvem (instalações, hardware, rede física, virtualização) é sempre da AWS. O cliente nunca tem acesso físico aos datacenters.', 'easy', 'Pense em quem consegue entrar no prédio.'),
  ('ccp', 'Segurança e Conformidade', 'Ao usar AWS Lambda, qual item continua sendo responsabilidade do cliente?', '[{"id": "a", "text": "A disponibilidade da infraestrutura de rede da Região"}, {"id": "b", "text": "O código da função e as permissões IAM que ela recebe"}, {"id": "c", "text": "A manutenção física dos servidores que executam a função"}, {"id": "d", "text": "A aplicação de patches no sistema operacional que executa a função"}]'::jsonb, array['b'], 'Em serviços gerenciados como o Lambda, a AWS cuida do sistema operacional, do runtime gerenciado e da infraestrutura. O cliente continua responsável pelo próprio código, pelos dados e por quem pode fazer o quê (IAM).', 'medium', 'Quanto mais gerenciado o serviço, menos sobra para o cliente, mas nunca zero.'),
  ('ccp', 'Segurança e Conformidade', 'Qual controle é classificado pela AWS como COMPARTILHADO, em que cada parte cuida da sua camada?', '[{"id": "a", "text": "Gerenciamento de patches"}, {"id": "b", "text": "Controles físicos e ambientais dos datacenters"}, {"id": "c", "text": "Proteção dos dados que o cliente armazena"}, {"id": "d", "text": "Escolha de quais usuários podem acessar a conta"}]'::jsonb, array['a'], 'Patches são um controle compartilhado: a AWS corrige a infraestrutura e o cliente corrige o sistema operacional convidado e as aplicações. Controles físicos são herdados da AWS; dados e acessos são do cliente.', 'hard', 'Cada lado corrige a sua própria camada.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa em auditoria quer usar os controles de segurança física e ambiental da AWS como evidência para o próprio programa de conformidade. Como esses controles são chamados no modelo de responsabilidade compartilhada?', '[{"id": "a", "text": "Controles opcionais"}, {"id": "b", "text": "Controles herdados"}, {"id": "c", "text": "Controles específicos do cliente"}, {"id": "d", "text": "Controles compartilhados"}]'::jsonb, array['b'], 'Controles herdados são aqueles que o cliente recebe integralmente da AWS, como os físicos e ambientais, e pode referenciar nas próprias auditorias.', 'hard', 'O cliente não implementa nada, apenas recebe.'),
  ('ccp', 'Segurança e Conformidade', 'Qual característica descreve um security group?', '[{"id": "a", "text": "Funciona no nível da instância, é stateful e só aceita regras de permissão"}, {"id": "b", "text": "Criptografa o tráfego entre instâncias automaticamente"}, {"id": "c", "text": "Bloqueia ataques de injeção de SQL na camada de aplicação"}, {"id": "d", "text": "Funciona no nível da sub-rede, é stateless e aceita regras de negação"}]'::jsonb, array['a'], 'Security groups são firewalls virtuais associados a interfaces de rede. São stateful (a resposta de uma conexão permitida volta automaticamente) e possuem apenas regras de allow.', 'easy', 'Lembre onde ele é aplicado e se ele guarda o estado da conexão.'),
  ('ccp', 'Segurança e Conformidade', 'O time de segurança precisa bloquear um endereço IP específico que está atacando todas as instâncias de uma sub-rede. Qual recurso permite criar essa regra de negação?', '[{"id": "a", "text": "Network ACL (NACL)"}, {"id": "b", "text": "Internet gateway"}, {"id": "c", "text": "Tabela de rotas"}, {"id": "d", "text": "Security group"}]'::jsonb, array['a'], 'NACLs atuam no nível da sub-rede e aceitam regras de allow e deny avaliadas em ordem numérica. Security groups não têm regras de negação.', 'medium', 'Você precisa de uma regra que NEGA, não que permite.'),
  ('ccp', 'Segurança e Conformidade', 'Quais afirmações sobre security groups estão corretas? (Escolha DUAS)', '[{"id": "a", "text": "Por padrão, um novo security group bloqueia todo o tráfego de entrada"}, {"id": "b", "text": "É possível criar regras explícitas de negação para um IP"}, {"id": "c", "text": "Um security group é associado a uma sub-rede inteira"}, {"id": "d", "text": "Regras são avaliadas em ordem numérica, da menor para a maior"}, {"id": "e", "text": "O tráfego de resposta a uma conexão permitida é liberado automaticamente"}]'::jsonb, array['a', 'e'], 'Security groups começam sem regras de entrada (tudo bloqueado) e são stateful, então as respostas voltam sem regra extra. Ordem numérica, associação à sub-rede e regras de negação são características de NACLs.', 'medium', 'Compare mentalmente com as características de uma NACL.'),
  ('ccp', 'Segurança e Conformidade', 'O que a autenticação multifator (MFA) adiciona ao login na AWS?', '[{"id": "a", "text": "Uma segunda senha que deve ser trocada a cada login"}, {"id": "b", "text": "Uma segunda prova de identidade, como um código de aplicativo ou uma chave de segurança, além da senha"}, {"id": "c", "text": "Criptografia automática de todos os dados da conta"}, {"id": "d", "text": "Permissão para acessar várias contas com um único usuário"}]'::jsonb, array['b'], 'MFA exige algo que você tem (aplicativo autenticador, passkey ou chave física) além de algo que você sabe (senha). Mesmo com a senha vazada, o invasor não entra.', 'easy', 'Multi = mais de um fator de identidade.'),
  ('ccp', 'Segurança e Conformidade', 'Quais tipos de dispositivo MFA podem ser usados com usuários IAM e com o usuário root? (Escolha DUAS)', '[{"id": "a", "text": "Passkey ou chave de segurança FIDO2"}, {"id": "b", "text": "Código enviado por SMS"}, {"id": "c", "text": "Pergunta secreta cadastrada na conta"}, {"id": "d", "text": "Aplicativo autenticador virtual"}, {"id": "e", "text": "Código enviado para o e-mail do usuário"}]'::jsonb, array['a', 'd'], 'A AWS aceita aplicativos autenticadores (TOTP), passkeys e chaves de segurança FIDO2, além de tokens físicos TOTP. MFA por SMS deixou de ser suportado para usuários IAM, e pergunta secreta ou e-mail não são fatores de MFA.', 'hard', 'Pense em fatores resistentes a interceptação.'),
  ('ccp', 'Segurança e Conformidade', 'Um administrador quer exigir que todas as senhas de usuários IAM tenham no mínimo 14 caracteres e expirem a cada 90 dias. O que ele deve configurar?', '[{"id": "a", "text": "Uma regra no AWS WAF"}, {"id": "b", "text": "Uma chave no AWS KMS"}, {"id": "c", "text": "Um security group com regras de senha"}, {"id": "d", "text": "Uma política de senhas da conta no IAM"}]'::jsonb, array['d'], 'A política de senhas do IAM define comprimento mínimo, complexidade, expiração e reutilização para todos os usuários IAM da conta.', 'easy', 'É uma configuração da conta, dentro do próprio IAM.'),
  ('ccp', 'Segurança e Conformidade', 'Um desenvolvedor precisa usar a AWS CLI no próprio computador com um usuário IAM. Que tipo de credencial a CLI utiliza?', '[{"id": "a", "text": "Um certificado TLS emitido pelo ACM"}, {"id": "b", "text": "Usuário e senha do console"}, {"id": "c", "text": "O e-mail e a senha do usuário root"}, {"id": "d", "text": "Chaves de acesso (access key ID e secret access key)"}]'::jsonb, array['d'], 'Acesso programático (CLI, SDKs) usa chaves de acesso ou, preferencialmente, credenciais temporárias obtidas via IAM Identity Center. Senha é para o console.', 'easy', 'Console usa senha; e a linha de comando?'),
  ('ccp', 'Segurança e Conformidade', 'Em que formato as permissões de uma política IAM são escritas?', '[{"id": "a", "text": "Documento JSON com Effect, Action, Resource e, opcionalmente, Condition"}, {"id": "b", "text": "Script em Python executado a cada requisição"}, {"id": "c", "text": "Planilha CSV com uma linha por serviço"}, {"id": "d", "text": "Arquivo YAML do CloudFormation obrigatório"}]'::jsonb, array['a'], 'Políticas IAM são documentos JSON. Cada statement diz se permite ou nega (Effect), quais ações (Action), em quais recursos (Resource) e sob quais condições (Condition).', 'medium', 'É o mesmo formato usado em bucket policies.'),
  ('ccp', 'Segurança e Conformidade', 'Um usuário IAM recém-criado, sem nenhuma política anexada, tenta listar buckets S3. O que acontece?', '[{"id": "a", "text": "A requisição é permitida apenas no console"}, {"id": "b", "text": "A requisição é permitida porque o usuário pertence à conta"}, {"id": "c", "text": "A requisição é permitida, pois listar é uma ação somente leitura"}, {"id": "d", "text": "A requisição é negada, pois tudo é negado implicitamente até haver um Allow"}]'::jsonb, array['d'], 'No IAM o padrão é a negação implícita: nenhuma ação é permitida sem uma política que conceda explicitamente o acesso.', 'medium', 'Qual é o comportamento padrão do IAM sem nenhuma política?'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa com várias contas no AWS Organizations quer impedir que QUALQUER usuário das contas de desenvolvimento crie recursos fora da Região de São Paulo. Qual recurso usar?', '[{"id": "a", "text": "Uma política de senhas do IAM"}, {"id": "b", "text": "Um security group em cada VPC"}, {"id": "c", "text": "Service Control Policy (SCP) aplicada à unidade organizacional"}, {"id": "d", "text": "Uma tag obrigatória em cada recurso"}]'::jsonb, array['c'], 'SCPs definem o limite máximo de permissões das contas de uma OU, inclusive para administradores. Elas não concedem permissões, apenas restringem o que pode ser permitido.', 'medium', 'Você precisa de um limite que vale para a conta inteira.'),
  ('ccp', 'Segurança e Conformidade', 'Qual afirmação sobre Service Control Policies (SCPs) é verdadeira?', '[{"id": "a", "text": "Elas não concedem permissões; apenas limitam o máximo que as políticas IAM podem permitir nas contas-membro"}, {"id": "b", "text": "Elas são aplicadas também à conta de gerenciamento da organização"}, {"id": "c", "text": "Elas substituem as políticas IAM e concedem acesso diretamente aos usuários"}, {"id": "d", "text": "Elas afetam somente usuários IAM e nunca o usuário root das contas-membro"}]'::jsonb, array['a'], 'Uma SCP funciona como um teto: a permissão efetiva é a interseção entre a SCP e as políticas IAM. Ela vale até para o root das contas-membro, mas não afeta a conta de gerenciamento.', 'hard', 'Pense em teto, não em concessão.'),
  ('ccp', 'Segurança e Conformidade', 'Um auditor quer saber qual usuário apagou uma instância EC2 ontem às 15h e de qual endereço IP partiu a chamada. Qual serviço registra essa informação?', '[{"id": "a", "text": "Amazon CloudWatch"}, {"id": "b", "text": "AWS CloudTrail"}, {"id": "c", "text": "Amazon Inspector"}, {"id": "d", "text": "AWS Trusted Advisor"}]'::jsonb, array['b'], 'O CloudTrail registra as chamadas de API da conta: quem fez, qual ação, quando, de onde e com qual resultado. O histórico de eventos guarda 90 dias de eventos de gerenciamento, e trails permitem retenção maior no S3.', 'easy', 'Quem fez o quê e quando: é uma trilha de auditoria.'),
  ('ccp', 'Segurança e Conformidade', 'Qual é a principal diferença entre o Amazon CloudWatch e o AWS CloudTrail?', '[{"id": "a", "text": "CloudWatch monitora métricas, logs e alarmes de desempenho; CloudTrail registra as chamadas de API feitas na conta"}, {"id": "b", "text": "Os dois são o mesmo serviço com nomes diferentes por Região"}, {"id": "c", "text": "CloudWatch só funciona com EC2 e CloudTrail só com S3"}, {"id": "d", "text": "CloudWatch registra as chamadas de API; CloudTrail monitora o uso de CPU"}]'::jsonb, array['a'], 'CloudWatch responde ''como meus recursos estão se comportando?'' (métricas, logs, alarmes). CloudTrail responde ''quem fez o quê na conta?'' (auditoria de API).', 'medium', 'Um olha o desempenho, o outro olha as ações.'),
  ('ccp', 'Segurança e Conformidade', 'Qual serviço analisa automaticamente instâncias EC2, imagens de contêiner no ECR e funções Lambda em busca de vulnerabilidades de software conhecidas (CVEs)?', '[{"id": "a", "text": "AWS Artifact"}, {"id": "b", "text": "Amazon Macie"}, {"id": "c", "text": "Amazon Inspector"}, {"id": "d", "text": "AWS Shield"}]'::jsonb, array['c'], 'O Amazon Inspector faz gestão contínua de vulnerabilidades, verificando pacotes e exposição de rede não intencional em EC2, contêineres e Lambda.', 'medium', 'O foco é inspecionar software vulnerável.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa usa GuardDuty, Inspector e Macie e quer uma visão única de todos os alertas, além de checagens automáticas contra padrões como o CIS AWS Foundations. Qual serviço atende?', '[{"id": "a", "text": "AWS Config"}, {"id": "b", "text": "AWS Organizations"}, {"id": "c", "text": "Amazon Detective"}, {"id": "d", "text": "AWS Security Hub"}]'::jsonb, array['d'], 'O Security Hub agrega e prioriza findings de vários serviços de segurança e executa verificações automáticas contra padrões de boas práticas.', 'medium', 'É um painel central de segurança.'),
  ('ccp', 'Segurança e Conformidade', 'O GuardDuty gerou um alerta de comportamento suspeito em uma instância. O analista precisa investigar a causa raiz, visualizando as relações entre usuários, IPs e recursos ao longo do tempo. Qual serviço é projetado para isso?', '[{"id": "a", "text": "Amazon Detective"}, {"id": "b", "text": "Amazon Inspector"}, {"id": "c", "text": "AWS Artifact"}, {"id": "d", "text": "AWS Trusted Advisor"}]'::jsonb, array['a'], 'O Detective organiza logs e eventos em um grafo de comportamento para facilitar a investigação da causa raiz de achados de segurança.', 'hard', 'O verbo da questão é investigar.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa de pagamentos exige um módulo de segurança de hardware (HSM) dedicado, de locatário único, sobre o qual somente ela tenha controle das chaves. Qual serviço atende?', '[{"id": "a", "text": "AWS CloudHSM"}, {"id": "b", "text": "AWS Secrets Manager"}, {"id": "c", "text": "AWS Certificate Manager"}, {"id": "d", "text": "AWS KMS com chaves gerenciadas pela AWS"}]'::jsonb, array['a'], 'O CloudHSM fornece HSMs dedicados e validados pelo FIPS, nos quais o cliente gerencia as próprias chaves e usuários. O KMS usa HSMs compartilhados e gerenciados pela AWS.', 'medium', 'Dedicado e de locatário único são as palavras-chave.'),
  ('ccp', 'Segurança e Conformidade', 'Uma aplicação armazena a senha do banco RDS e precisa que ela seja trocada automaticamente a cada 30 dias, sem alterar o código. Qual serviço usar?', '[{"id": "a", "text": "AWS KMS"}, {"id": "b", "text": "Amazon Cognito"}, {"id": "c", "text": "AWS Secrets Manager"}, {"id": "d", "text": "AWS Certificate Manager"}]'::jsonb, array['c'], 'O Secrets Manager armazena segredos criptografados e oferece rotação automática integrada para bancos como RDS, Aurora e Redshift. A aplicação busca o valor atual pela API.', 'medium', 'Guardar e girar segredos automaticamente.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa de e-commerce sofre ataques DDoS frequentes e quer acesso 24/7 a uma equipe especializada da AWS durante os ataques, além de proteção contra aumento da fatura causado por eles. Qual serviço contratar?', '[{"id": "a", "text": "AWS Shield Advanced"}, {"id": "b", "text": "AWS Shield Standard"}, {"id": "c", "text": "Amazon GuardDuty"}, {"id": "d", "text": "AWS Firewall Manager"}]'::jsonb, array['a'], 'O Shield Advanced adiciona detecção avançada, acesso ao Shield Response Team (SRT) e proteção de custos para picos de escalabilidade causados por DDoS. O Standard é gratuito e automático, mas sem esses extras.', 'medium', 'Equipe de resposta e proteção de custos não estão no plano gratuito.'),
  ('ccp', 'Segurança e Conformidade', 'Uma API está recebendo milhares de requisições por minuto de poucos IPs, tentando adivinhar senhas. Qual recurso bloqueia automaticamente IPs que ultrapassam um limite de requisições?', '[{"id": "a", "text": "Regra baseada em taxa (rate-based rule) do AWS WAF"}, {"id": "b", "text": "Regra de saída em um security group"}, {"id": "c", "text": "Uma política de senhas do IAM"}, {"id": "d", "text": "Uma rota no Amazon Route 53"}]'::jsonb, array['a'], 'Regras baseadas em taxa do WAF contam requisições por IP e bloqueiam temporariamente quem passa do limite definido, mitigando força bruta e abuso na camada 7.', 'medium', 'O critério é a quantidade de requisições por origem.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa com 40 contas quer aplicar as mesmas regras do AWS WAF e de security groups em todas, de forma central, inclusive em contas novas. Qual serviço usar?', '[{"id": "a", "text": "AWS Systems Manager"}, {"id": "b", "text": "Amazon Inspector"}, {"id": "c", "text": "AWS Firewall Manager"}, {"id": "d", "text": "AWS Shield Standard"}]'::jsonb, array['c'], 'O Firewall Manager gerencia centralmente regras de WAF, Shield Advanced, security groups e firewalls de rede em todas as contas de um AWS Organizations, aplicando-as automaticamente a novos recursos.', 'hard', 'É um gerente central de firewalls para a organização.'),
  ('ccp', 'Segurança e Conformidade', 'Qual afirmação descreve corretamente a criptografia padrão do Amazon S3 para objetos novos?', '[{"id": "a", "text": "O S3 não oferece criptografia em repouso"}, {"id": "b", "text": "A criptografia só existe na classe S3 Glacier"}, {"id": "c", "text": "Todo objeto novo é criptografado em repouso por padrão com chaves gerenciadas pelo S3 (SSE-S3)"}, {"id": "d", "text": "Os objetos só são criptografados se o cliente instalar um agente"}]'::jsonb, array['c'], 'Desde 2023 o S3 aplica SSE-S3 a todos os novos objetos sem custo adicional. O cliente pode optar por SSE-KMS ou chaves próprias quando precisa de mais controle e auditoria.', 'medium', 'Desde 2023 não é preciso ligar nada para ter criptografia básica.'),
  ('ccp', 'Segurança e Conformidade', 'Qual serviço identifica buckets S3, roles IAM e chaves KMS compartilhados com entidades fora da sua conta ou organização?', '[{"id": "a", "text": "AWS Trusted Advisor"}, {"id": "b", "text": "IAM Access Analyzer"}, {"id": "c", "text": "Amazon Inspector"}, {"id": "d", "text": "Amazon Macie"}]'::jsonb, array['b'], 'O IAM Access Analyzer analisa políticas baseadas em recursos e aponta quais recursos estão acessíveis por principais externos, além de identificar acessos não utilizados.', 'medium', 'O foco é quem de FORA consegue acessar.'),
  ('ccp', 'Segurança e Conformidade', 'O auditor pede uma lista de todos os usuários IAM da conta com o status das senhas, chaves de acesso e MFA. Qual recurso gera esse documento?', '[{"id": "a", "text": "AWS Artifact"}, {"id": "b", "text": "Relatório de credenciais do IAM"}, {"id": "c", "text": "Histórico de eventos do CloudTrail"}, {"id": "d", "text": "AWS Cost and Usage Report"}]'::jsonb, array['b'], 'O relatório de credenciais do IAM é um CSV com todos os usuários e o estado de suas credenciais: última troca de senha, idade das chaves e se o MFA está ativo.', 'easy', 'É um relatório gerado dentro do próprio IAM.'),
  ('ccp', 'Segurança e Conformidade', 'Uma clínica vai processar dados de saúde protegidos pela HIPAA na AWS e precisa assinar o Business Associate Addendum (BAA). Onde esse acordo é aceito?', '[{"id": "a", "text": "No AWS Trusted Advisor"}, {"id": "b", "text": "No console do AWS Config"}, {"id": "c", "text": "No AWS Artifact, na seção de acordos"}, {"id": "d", "text": "No AWS Marketplace"}]'::jsonb, array['c'], 'Além dos relatórios de conformidade, o AWS Artifact permite revisar e aceitar acordos com a AWS, como o BAA exigido para workloads sujeitos à HIPAA.', 'medium', 'É o mesmo serviço onde se baixam relatórios SOC e ISO.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa precisa garantir que dados de clientes brasileiros nunca saiam do país. O que a AWS faz com os dados armazenados na Região sa-east-1?', '[{"id": "a", "text": "Os dados só ficam no Brasil se o cliente contratar o suporte Enterprise"}, {"id": "b", "text": "A AWS replica automaticamente todos os dados para os Estados Unidos"}, {"id": "c", "text": "Os dados são distribuídos entre todas as Regiões para maior durabilidade"}, {"id": "d", "text": "Os dados permanecem na Região escolhida e não são movidos pela AWS sem ação do cliente"}]'::jsonb, array['d'], 'O cliente escolhe a Região e controla onde seus dados ficam. A AWS não replica nem move conteúdo para outra Região sem ação do cliente, o que ajuda a atender requisitos de residência de dados.', 'medium', 'Quem decide a localização dos dados?'),
  ('ccp', 'Segurança e Conformidade', 'Um aplicativo mobile precisa de cadastro e login de clientes, inclusive com contas Google e Apple. Qual serviço AWS oferece isso?', '[{"id": "a", "text": "AWS Organizations"}, {"id": "b", "text": "AWS Directory Service"}, {"id": "c", "text": "AWS IAM Identity Center"}, {"id": "d", "text": "Amazon Cognito"}]'::jsonb, array['d'], 'O Cognito gerencia identidades de usuários finais de aplicações: cadastro, login, MFA e federação com provedores sociais. O IAM Identity Center é para a força de trabalho acessar contas AWS.', 'easy', 'Os usuários são clientes do aplicativo, não funcionários.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa quer usar o Active Directory da Microsoft como serviço gerenciado na AWS para aplicações Windows, sem administrar controladores de domínio. Qual serviço usar?', '[{"id": "a", "text": "AWS Secrets Manager"}, {"id": "b", "text": "AWS IAM Identity Center"}, {"id": "c", "text": "AWS Directory Service (AWS Managed Microsoft AD)"}, {"id": "d", "text": "Amazon Cognito"}]'::jsonb, array['c'], 'O AWS Managed Microsoft AD fornece um Active Directory real e gerenciado pela AWS, com alta disponibilidade e patches automáticos, que pode confiar no AD local.', 'medium', 'O requisito é um Active Directory de verdade.'),
  ('ccp', 'Segurança e Conformidade', 'Ao usar Amazon DynamoDB, qual responsabilidade é do cliente?', '[{"id": "a", "text": "Aplicar patches no software do banco"}, {"id": "b", "text": "Definir quem pode acessar as tabelas e classificar os dados armazenados"}, {"id": "c", "text": "Substituir discos com defeito"}, {"id": "d", "text": "Garantir a replicação entre Zonas de Disponibilidade"}]'::jsonb, array['b'], 'O DynamoDB é totalmente gerenciado: a AWS cuida de software, hardware e replicação. O cliente continua responsável pelo controle de acesso (IAM) e pelos dados.', 'medium', 'Em serviço gerenciado, o que sobra para o cliente?'),
  ('ccp', 'Segurança e Conformidade', 'Qual é a recomendação da AWS para o uso do usuário root no dia a dia?', '[{"id": "a", "text": "Compartilhar as credenciais root com a equipe de operações"}, {"id": "b", "text": "Não usá-lo em tarefas cotidianas; criar identidades administrativas e reservar o root para tarefas que só ele executa"}, {"id": "c", "text": "Criar chaves de acesso root para automações"}, {"id": "d", "text": "Usá-lo em todas as tarefas para evitar problemas de permissão"}]'::jsonb, array['b'], 'O root tem acesso irrestrito. A boa prática é protegê-lo com MFA, não criar chaves de acesso para ele e usar identidades com menos privilégio no trabalho diário.', 'easy', 'Quanto mais poderosa a credencial, menos ela deve ser usada.'),
  ('ccp', 'Segurança e Conformidade', 'A AWS recebeu relatos de que instâncias de uma conta estão enviando spam. Uma pessoa externa que identificou esse abuso deve avisar qual equipe?', '[{"id": "a", "text": "O AWS Support Concierge"}, {"id": "b", "text": "A equipe de Trust & Safety (abuso) da AWS"}, {"id": "c", "text": "O Technical Account Manager do cliente"}, {"id": "d", "text": "A equipe do AWS Marketplace"}]'::jsonb, array['b'], 'Suspeitas de uso abusivo de recursos AWS (spam, ataques, conteúdo ilegal) são reportadas à equipe de Trust & Safety da AWS, que investiga e notifica o dono da conta.', 'easy', 'É um canal específico para denúncias de abuso.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa quer comprar um firewall de um fornecedor terceiro e pagar diretamente na fatura AWS. Onde encontrar esse produto?', '[{"id": "a", "text": "AWS Artifact"}, {"id": "b", "text": "AWS Config"}, {"id": "c", "text": "AWS Marketplace"}, {"id": "d", "text": "AWS Security Hub"}]'::jsonb, array['c'], 'O AWS Marketplace é um catálogo de software de terceiros, inclusive soluções de segurança, que podem ser contratadas e cobradas na própria fatura AWS.', 'easy', 'É uma loja de software de terceiros.'),
  ('ccp', 'Segurança e Conformidade', 'Qual recurso captura informações sobre o tráfego IP que entra e sai das interfaces de rede de uma VPC, útil para investigar conexões rejeitadas?', '[{"id": "a", "text": "AWS Config"}, {"id": "b", "text": "Amazon Macie"}, {"id": "c", "text": "VPC Flow Logs"}, {"id": "d", "text": "AWS CloudTrail"}]'::jsonb, array['c'], 'VPC Flow Logs registram metadados do tráfego (origem, destino, portas, ação ACCEPT ou REJECT) e podem ser enviados ao CloudWatch Logs ou ao S3.', 'medium', 'O assunto é tráfego de rede, não chamadas de API.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa quer configurar rapidamente um ambiente com várias contas seguindo boas práticas, com contas de log e auditoria e controles preventivos e detectivos já aplicados. Qual serviço automatiza isso?', '[{"id": "a", "text": "AWS Service Catalog"}, {"id": "b", "text": "AWS Config"}, {"id": "c", "text": "AWS Trusted Advisor"}, {"id": "d", "text": "AWS Control Tower"}]'::jsonb, array['d'], 'O Control Tower cria uma landing zone baseada em AWS Organizations, com contas de log e auditoria e controles (guardrails) preventivos e detectivos aplicados às contas.', 'hard', 'Landing zone multi-conta pronta é a pista.'),
  ('ccp', 'Segurança e Conformidade', 'Uma aplicação na conta A precisa acessar temporariamente um bucket na conta B sem criar usuários ou chaves permanentes. Qual é a abordagem recomendada?', '[{"id": "a", "text": "Tornar o bucket público durante a operação"}, {"id": "b", "text": "Compartilhar as credenciais root da conta B"}, {"id": "c", "text": "Criar uma role na conta B que a conta A possa assumir, obtendo credenciais temporárias"}, {"id": "d", "text": "Criar um usuário IAM na conta B e copiar as chaves de acesso para a conta A"}]'::jsonb, array['c'], 'Roles com relação de confiança entre contas permitem obter credenciais temporárias via AWS STS, sem segredos de longa duração.', 'medium', 'Credenciais temporárias vêm de assumir algo.'),
  ('ccp', 'Segurança e Conformidade', 'Quais práticas seguem as recomendações de segurança do IAM? (Escolha DUAS)', '[{"id": "a", "text": "Conceder apenas as permissões necessárias e revisar acessos não utilizados"}, {"id": "b", "text": "Usar o usuário root para automações agendadas"}, {"id": "c", "text": "Exigir MFA para usuários com acesso ao console"}, {"id": "d", "text": "Incluir chaves de acesso no código-fonte da aplicação"}, {"id": "e", "text": "Criar um único usuário administrador compartilhado pela equipe"}]'::jsonb, array['a', 'c'], 'MFA e menor privilégio com revisão periódica são pilares do IAM. Credenciais compartilhadas, chaves no código e uso do root aumentam o risco de vazamento e dificultam a auditoria.', 'medium', 'Elimine as opções que espalham ou expõem credenciais.'),
  ('ccp', 'Segurança e Conformidade', 'Quais serviços ajudam a proteger dados EM REPOUSO com chaves criptográficas gerenciadas? (Escolha DUAS)', '[{"id": "a", "text": "Amazon GuardDuty"}, {"id": "b", "text": "AWS Key Management Service (KMS)"}, {"id": "c", "text": "AWS Certificate Manager"}, {"id": "d", "text": "AWS CloudHSM"}, {"id": "e", "text": "AWS Shield"}]'::jsonb, array['b', 'd'], 'KMS e CloudHSM gerenciam chaves usadas para criptografar dados armazenados. O ACM cuida de certificados para dados em trânsito, o Shield protege contra DDoS e o GuardDuty detecta ameaças.', 'hard', 'Separe criptografia em repouso, em trânsito e detecção de ameaças.'),
  ('ccp', 'Segurança e Conformidade', 'Uma empresa quer centralizar logs de segurança de várias contas e fontes em um data lake no formato padrão OCSF para análise. Qual serviço foi criado para isso?', '[{"id": "a", "text": "Amazon Security Lake"}, {"id": "b", "text": "Amazon Detective"}, {"id": "c", "text": "AWS Audit Manager"}, {"id": "d", "text": "AWS Artifact"}]'::jsonb, array['a'], 'O Amazon Security Lake coleta e normaliza dados de segurança de serviços AWS e de terceiros no formato OCSF, armazenando-os em um data lake na conta do cliente.', 'medium', 'O nome do serviço lembra onde os dados ficam.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma aplicação de simulações científicas precisa de muito processamento de CPU por núcleo. Qual família de instâncias EC2 é mais indicada?', '[{"id": "a", "text": "Otimizada para computação (família C)"}, {"id": "b", "text": "Otimizada para armazenamento (família I)"}, {"id": "c", "text": "Uso geral com desempenho expansível (família T)"}, {"id": "d", "text": "Otimizada para memória (família R)"}]'::jsonb, array['a'], 'Instâncias otimizadas para computação têm alta relação CPU por memória, ideais para processamento intensivo, codificação de vídeo e simulações.', 'easy', 'O gargalo é o processador.'),
  ('ccp', 'Tecnologia e Serviços', 'Um banco de dados em memória precisa de centenas de GiB de RAM em uma única instância. Qual família EC2 escolher?', '[{"id": "a", "text": "Otimizada para computação (família C)"}, {"id": "b", "text": "Computação acelerada (família P ou G)"}, {"id": "c", "text": "Uso geral com desempenho expansível (família T)"}, {"id": "d", "text": "Otimizada para memória (família R ou X)"}]'::jsonb, array['d'], 'Instâncias otimizadas para memória oferecem muita RAM por vCPU, indicadas para bancos em memória, caches grandes e análises em tempo real.', 'medium', 'O recurso escasso é a RAM.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma equipe vai treinar modelos de deep learning que se beneficiam de GPUs. Qual categoria de instância EC2 usar?', '[{"id": "a", "text": "Otimizada para armazenamento"}, {"id": "b", "text": "Otimizada para memória"}, {"id": "c", "text": "Uso geral"}, {"id": "d", "text": "Computação acelerada"}]'::jsonb, array['d'], 'Instâncias de computação acelerada trazem GPUs ou chips dedicados (como AWS Trainium e Inferentia) para treinamento e inferência de ML, gráficos e HPC.', 'medium', 'Procure a categoria que traz hardware especializado.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma aplicação deve manter sempre pelo menos 4 instâncias EC2 saudáveis e substituir automaticamente as que falharem. Qual recurso faz isso?', '[{"id": "a", "text": "Amazon EC2 Auto Scaling"}, {"id": "b", "text": "Amazon CloudFront"}, {"id": "c", "text": "Amazon Route 53"}, {"id": "d", "text": "AWS Config"}]'::jsonb, array['a'], 'Um grupo do Auto Scaling mantém a capacidade desejada, substitui instâncias com falha nas verificações de saúde e ajusta a quantidade conforme políticas de escala.', 'easy', 'O recurso cuida da quantidade de instâncias.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma aplicação web precisa encaminhar /api para um grupo de instâncias e /imagens para outro, com base no caminho da URL. Qual tipo de load balancer usar?', '[{"id": "a", "text": "Network Load Balancer"}, {"id": "b", "text": "Application Load Balancer"}, {"id": "c", "text": "Classic Load Balancer"}, {"id": "d", "text": "Gateway Load Balancer"}]'::jsonb, array['b'], 'O Application Load Balancer opera na camada 7 (HTTP/HTTPS) e roteia por caminho, host, cabeçalhos e parâmetros.', 'medium', 'O roteamento depende de informações HTTP.'),
  ('ccp', 'Tecnologia e Serviços', 'Um jogo online usa tráfego UDP e exige latência extremamente baixa, com milhões de requisições por segundo e IP estático por Zona de Disponibilidade. Qual load balancer atende?', '[{"id": "a", "text": "Classic Load Balancer"}, {"id": "b", "text": "Application Load Balancer"}, {"id": "c", "text": "Network Load Balancer"}, {"id": "d", "text": "Amazon API Gateway"}]'::jsonb, array['c'], 'O Network Load Balancer opera na camada 4 (TCP, UDP, TLS), tem latência ultrabaixa, escala para milhões de requisições e oferece IP estático por AZ.', 'hard', 'UDP e camada 4 eliminam as opções focadas em HTTP.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma equipe quer executar contêineres sem gerenciar servidores ou clusters de instâncias EC2. Qual opção de computação usar com Amazon ECS ou EKS?', '[{"id": "a", "text": "Amazon EC2 Dedicated Hosts"}, {"id": "b", "text": "AWS Fargate"}, {"id": "c", "text": "AWS Outposts"}, {"id": "d", "text": "Amazon Lightsail"}]'::jsonb, array['b'], 'O Fargate é um mecanismo de computação serverless para contêineres: você define CPU e memória da tarefa e a AWS cuida da infraestrutura.', 'easy', 'É a opção serverless para contêineres.'),
  ('ccp', 'Tecnologia e Serviços', 'Onde uma equipe armazena e versiona as imagens Docker que serão usadas pelo ECS e pelo EKS?', '[{"id": "a", "text": "Amazon EFS"}, {"id": "b", "text": "AWS CodeArtifact"}, {"id": "c", "text": "Amazon S3 Glacier"}, {"id": "d", "text": "Amazon Elastic Container Registry (ECR)"}]'::jsonb, array['d'], 'O ECR é um registro de imagens de contêiner gerenciado, integrado ao IAM e com varredura de vulnerabilidades.', 'easy', 'Contêineres precisam de um registro de imagens.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa já usa Kubernetes no datacenter e quer levar os mesmos manifests para a AWS com o plano de controle gerenciado. Qual serviço escolher?', '[{"id": "a", "text": "AWS Elastic Beanstalk"}, {"id": "b", "text": "Amazon Elastic Kubernetes Service (EKS)"}, {"id": "c", "text": "Amazon Elastic Container Service (ECS)"}, {"id": "d", "text": "AWS Batch"}]'::jsonb, array['b'], 'O EKS oferece Kubernetes compatível com o upstream, com o plano de controle gerenciado pela AWS. O ECS é o orquestrador próprio da AWS, com outra API.', 'medium', 'O requisito é manter o Kubernetes.'),
  ('ccp', 'Tecnologia e Serviços', 'Um pequeno negócio quer um servidor virtual simples para um blog WordPress, com preço mensal fixo e configuração fácil. Qual serviço é mais indicado?', '[{"id": "a", "text": "Amazon EMR"}, {"id": "b", "text": "Amazon EKS"}, {"id": "c", "text": "Amazon Lightsail"}, {"id": "d", "text": "AWS Outposts"}]'::jsonb, array['c'], 'O Lightsail oferece servidores virtuais, bancos e balanceadores com planos de preço fixo e console simplificado, ideal para projetos pequenos.', 'easy', 'Simplicidade e preço previsível.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa roda milhares de jobs de processamento em lote toda noite e quer que a AWS provisione a quantidade certa de computação automaticamente. Qual serviço usar?', '[{"id": "a", "text": "Amazon AppStream 2.0"}, {"id": "b", "text": "AWS Step Functions"}, {"id": "c", "text": "Amazon Lightsail"}, {"id": "d", "text": "AWS Batch"}]'::jsonb, array['d'], 'O AWS Batch gerencia filas de jobs e provisiona dinamicamente a capacidade de computação (EC2, Spot ou Fargate) adequada aos jobs em lote.', 'medium', 'O nome do serviço descreve o tipo de carga.'),
  ('ccp', 'Tecnologia e Serviços', 'Documentos de RH são acessados com frequência no primeiro mês e quase nunca depois, mas precisam ser recuperados em milissegundos quando solicitados. Qual classe S3 usar após o primeiro mês?', '[{"id": "a", "text": "S3 Standard"}, {"id": "b", "text": "S3 Express One Zone"}, {"id": "c", "text": "S3 Glacier Deep Archive"}, {"id": "d", "text": "S3 Standard-Infrequent Access"}]'::jsonb, array['d'], 'Standard-IA tem armazenamento mais barato que o Standard e acesso em milissegundos, com cobrança por GB recuperado. Glacier Deep Archive pode levar horas para recuperar.', 'medium', 'Acesso raro, mas imediato quando acontece.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa precisa guardar registros por 10 anos por exigência legal, raramente consultados, e aceita esperar até 12 horas para recuperá-los. Qual é a classe S3 mais barata?', '[{"id": "a", "text": "S3 Standard-Infrequent Access"}, {"id": "b", "text": "S3 Glacier Deep Archive"}, {"id": "c", "text": "S3 Intelligent-Tiering"}, {"id": "d", "text": "S3 One Zone-Infrequent Access"}]'::jsonb, array['b'], 'Glacier Deep Archive é a classe de menor custo do S3, feita para retenção de longo prazo, com recuperação padrão em até 12 horas.', 'medium', 'Menor custo e longa espera são aceitáveis.'),
  ('ccp', 'Tecnologia e Serviços', 'Um data lake tem objetos com padrão de acesso desconhecido e imprevisível. Qual classe S3 move os objetos automaticamente entre camadas de acesso para economizar?', '[{"id": "a", "text": "S3 Intelligent-Tiering"}, {"id": "b", "text": "S3 Standard"}, {"id": "c", "text": "S3 One Zone-Infrequent Access"}, {"id": "d", "text": "S3 Glacier Flexible Retrieval"}]'::jsonb, array['a'], 'O Intelligent-Tiering monitora o acesso de cada objeto e o move entre camadas frequente, infrequente e de arquivamento, sem taxas de recuperação.', 'medium', 'Quando você não sabe o padrão, deixe o S3 decidir.'),
  ('ccp', 'Tecnologia e Serviços', 'Miniaturas de imagens podem ser recriadas a qualquer momento a partir dos originais e raramente são acessadas. Qual classe S3 oferece o menor custo aceitando armazenar em uma única AZ?', '[{"id": "a", "text": "S3 Standard"}, {"id": "b", "text": "S3 Glacier Deep Archive"}, {"id": "c", "text": "S3 Intelligent-Tiering"}, {"id": "d", "text": "S3 One Zone-Infrequent Access"}]'::jsonb, array['d'], 'One Zone-IA armazena em uma única AZ e custa menos que o Standard-IA. Serve para dados reproduzíveis, já que a perda da AZ pode apagar os objetos. Deep Archive não serviria por causa do tempo de recuperação.', 'hard', 'Os dados são reproduzíveis, então a redundância entre AZs é dispensável.'),
  ('ccp', 'Tecnologia e Serviços', 'Como mover automaticamente objetos S3 para classes mais baratas após 30 dias e apagá-los após 1 ano?', '[{"id": "a", "text": "Ativando o versionamento do bucket"}, {"id": "b", "text": "Habilitando o S3 Transfer Acceleration"}, {"id": "c", "text": "Configurando uma política de ciclo de vida no bucket"}, {"id": "d", "text": "Criando uma função Lambda que copia os objetos todo dia"}]'::jsonb, array['c'], 'Regras de ciclo de vida do S3 fazem transições de classe e expirações automáticas com base na idade dos objetos, sem código.', 'easy', 'É uma configuração nativa do bucket.'),
  ('ccp', 'Tecnologia e Serviços', 'Um usuário apagou por engano arquivos importantes de um bucket S3. Qual recurso, ativado previamente, permitiria recuperá-los?', '[{"id": "a", "text": "S3 Transfer Acceleration"}, {"id": "b", "text": "Classe S3 One Zone-IA"}, {"id": "c", "text": "Versionamento do S3"}, {"id": "d", "text": "Hospedagem de site estático"}]'::jsonb, array['c'], 'Com o versionamento, uma exclusão apenas cria um marcador de exclusão e as versões anteriores continuam disponíveis para restauração.', 'easy', 'Guardar versões anteriores evita perdas.'),
  ('ccp', 'Tecnologia e Serviços', 'Qual afirmação descreve um volume Amazon EBS?', '[{"id": "a", "text": "Armazenamento de objetos acessível de qualquer Região pela internet"}, {"id": "b", "text": "Armazenamento em bloco persistente, anexado a instâncias na mesma Zona de Disponibilidade"}, {"id": "c", "text": "Sistema de arquivos compartilhado montado por milhares de instâncias em várias AZs"}, {"id": "d", "text": "Armazenamento temporário que é apagado quando a instância para"}]'::jsonb, array['b'], 'O EBS fornece discos em bloco que persistem independentemente da vida da instância e ficam na mesma AZ dela. Para outra AZ, usa-se snapshot.', 'medium', 'Pense em um disco rígido de rede.'),
  ('ccp', 'Tecnologia e Serviços', 'Um processamento usa um disco local muito rápido para arquivos temporários que podem ser perdidos. O que acontece com os dados do instance store quando a instância é interrompida (stop)?', '[{"id": "a", "text": "São convertidos em um snapshot EBS"}, {"id": "b", "text": "São copiados automaticamente para o S3"}, {"id": "c", "text": "São perdidos, pois o instance store é armazenamento temporário"}, {"id": "d", "text": "Permanecem disponíveis até a instância ser encerrada"}]'::jsonb, array['c'], 'O instance store fica em discos fisicamente ligados ao host. Os dados sobrevivem a reinicializações, mas são perdidos ao parar, hibernar ou encerrar a instância.', 'medium', 'É armazenamento efêmero.'),
  ('ccp', 'Tecnologia e Serviços', 'Servidores Windows precisam de um compartilhamento de arquivos SMB gerenciado, integrado ao Active Directory. Qual serviço usar?', '[{"id": "a", "text": "Amazon EBS"}, {"id": "b", "text": "Amazon FSx for Windows File Server"}, {"id": "c", "text": "Amazon S3"}, {"id": "d", "text": "Amazon EFS"}]'::jsonb, array['b'], 'O FSx for Windows File Server fornece sistemas de arquivos Windows nativos com SMB, NTFS e integração ao AD. O EFS é voltado a clientes Linux via NFS.', 'medium', 'SMB e Windows apontam para a família FSx.'),
  ('ccp', 'Tecnologia e Serviços', 'Um cluster de computação de alto desempenho (HPC) precisa de um sistema de arquivos paralelo com centenas de GB/s de throughput, integrado ao S3. Qual serviço atende?', '[{"id": "a", "text": "Amazon FSx for Windows File Server"}, {"id": "b", "text": "Amazon FSx for Lustre"}, {"id": "c", "text": "AWS Storage Gateway"}, {"id": "d", "text": "Amazon EFS"}]'::jsonb, array['b'], 'O FSx for Lustre oferece um sistema de arquivos paralelo de alto desempenho para HPC e ML, podendo ler e gravar dados diretamente de buckets S3.', 'hard', 'Lustre é o sistema de arquivos clássico de supercomputadores.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer que aplicações do datacenter continuem gravando em compartilhamentos de arquivos locais, enquanto os dados são armazenados no S3. Qual serviço faz essa ponte híbrida?', '[{"id": "a", "text": "Amazon CloudFront"}, {"id": "b", "text": "AWS Direct Connect"}, {"id": "c", "text": "AWS Storage Gateway"}, {"id": "d", "text": "AWS Snowball Edge"}]'::jsonb, array['c'], 'O Storage Gateway expõe protocolos de arquivo, volume ou fita no ambiente local e armazena os dados na AWS, com cache local para acesso rápido.', 'medium', 'Um gateway conecta os dois mundos.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer definir em um único lugar a política de backup de EC2, EBS, RDS, DynamoDB e EFS, com retenção e cópias entre Regiões. Qual serviço usar?', '[{"id": "a", "text": "AWS DataSync"}, {"id": "b", "text": "AWS Backup"}, {"id": "c", "text": "AWS Storage Gateway"}, {"id": "d", "text": "Amazon S3 Glacier"}]'::jsonb, array['b'], 'O AWS Backup centraliza e automatiza backups de vários serviços AWS com planos, retenção, cópias entre Regiões e contas e relatórios de conformidade.', 'easy', 'O nome do serviço já diz o que ele centraliza.'),
  ('ccp', 'Tecnologia e Serviços', 'Um banco RDS de produção precisa continuar disponível se a Zona de Disponibilidade principal falhar, com failover automático. Qual recurso ativar?', '[{"id": "a", "text": "Réplica de leitura na mesma AZ"}, {"id": "b", "text": "Aumentar o tipo da instância"}, {"id": "c", "text": "Snapshot manual diário"}, {"id": "d", "text": "Implantação Multi-AZ"}]'::jsonb, array['d'], 'No Multi-AZ, o RDS mantém uma instância standby em outra AZ com replicação síncrona e faz failover automático em caso de falha.', 'medium', 'Alta disponibilidade entre AZs.'),
  ('ccp', 'Tecnologia e Serviços', 'Um site de notícias tem muito mais leituras do que escritas e o banco RDS está sobrecarregado com consultas. Qual recurso alivia a carga de leitura?', '[{"id": "a", "text": "Réplicas de leitura (read replicas)"}, {"id": "b", "text": "Ativar a criptografia do banco"}, {"id": "c", "text": "Implantação Multi-AZ standby"}, {"id": "d", "text": "Aumentar o período de retenção de backup"}]'::jsonb, array['a'], 'Réplicas de leitura recebem cópias assíncronas dos dados e atendem consultas de leitura, escalando horizontalmente as leituras. A standby Multi-AZ não atende tráfego.', 'medium', 'O problema é volume de leitura, não disponibilidade.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer executar consultas analíticas complexas sobre petabytes de dados históricos de vendas. Qual serviço de data warehouse usar?', '[{"id": "a", "text": "Amazon Neptune"}, {"id": "b", "text": "Amazon DynamoDB"}, {"id": "c", "text": "Amazon Redshift"}, {"id": "d", "text": "Amazon ElastiCache"}]'::jsonb, array['c'], 'O Redshift é um data warehouse colunar e massivamente paralelo, otimizado para consultas analíticas (OLAP) em grandes volumes.', 'easy', 'Data warehouse é a palavra-chave.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma aplicação faz a mesma consulta pesada ao banco milhares de vezes por minuto. Qual serviço adiciona uma camada de cache em memória para reduzir a latência?', '[{"id": "a", "text": "AWS Backup"}, {"id": "b", "text": "Amazon S3 Glacier"}, {"id": "c", "text": "Amazon Redshift"}, {"id": "d", "text": "Amazon ElastiCache"}]'::jsonb, array['d'], 'O ElastiCache oferece caches em memória gerenciados (compatíveis com Valkey, Redis OSS e Memcached), com latência de microssegundos para dados acessados com frequência.', 'easy', 'Cache em memória.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma rede social precisa consultar relações como ''amigos de amigos que curtiram a mesma página''. Qual banco de dados gerenciado é mais adequado?', '[{"id": "a", "text": "Amazon Neptune"}, {"id": "b", "text": "Amazon RDS for MySQL"}, {"id": "c", "text": "Amazon DocumentDB"}, {"id": "d", "text": "Amazon Redshift"}]'::jsonb, array['a'], 'O Neptune é um banco de grafos gerenciado, ideal para relações altamente conectadas, como redes sociais, recomendações e detecção de fraude.', 'medium', 'Relações entre entidades formam um grafo.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma aplicação usa MongoDB e a equipe quer migrar para um serviço gerenciado compatível com as mesmas APIs. Qual serviço escolher?', '[{"id": "a", "text": "Amazon DocumentDB"}, {"id": "b", "text": "Amazon Neptune"}, {"id": "c", "text": "Amazon Aurora"}, {"id": "d", "text": "Amazon Keyspaces"}]'::jsonb, array['a'], 'O Amazon DocumentDB é um banco de documentos JSON gerenciado e compatível com MongoDB.', 'medium', 'Banco de documentos compatível com MongoDB.'),
  ('ccp', 'Tecnologia e Serviços', 'Instâncias em uma sub-rede privada precisam baixar atualizações da internet sem receber conexões iniciadas de fora. Qual recurso usar?', '[{"id": "a", "text": "Endereço IP elástico em cada instância"}, {"id": "b", "text": "VPC peering com outra conta"}, {"id": "c", "text": "NAT gateway em uma sub-rede pública"}, {"id": "d", "text": "Internet gateway anexado diretamente à sub-rede privada"}]'::jsonb, array['c'], 'O NAT gateway permite conexões de saída de sub-redes privadas e bloqueia conexões iniciadas da internet. Ele fica em uma sub-rede pública com rota para o internet gateway.', 'medium', 'Só saída, nunca entrada.'),
  ('ccp', 'Tecnologia e Serviços', 'O que torna uma sub-rede de uma VPC ''pública''?', '[{"id": "a", "text": "Ter um security group que libera a porta 80"}, {"id": "b", "text": "Estar na primeira Zona de Disponibilidade da Região"}, {"id": "c", "text": "Ter uma rota na tabela de rotas para um internet gateway"}, {"id": "d", "text": "Ter o nome ''public'' na descrição"}]'::jsonb, array['c'], 'Uma sub-rede é pública quando sua tabela de rotas direciona o tráfego da internet (0.0.0.0/0) para um internet gateway.', 'easy', 'A resposta está na tabela de rotas.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa precisa conectar seu datacenter à VPC hoje mesmo, de forma criptografada pela internet, sem esperar a instalação de um circuito dedicado. Qual opção usar?', '[{"id": "a", "text": "AWS Direct Connect"}, {"id": "b", "text": "Amazon CloudFront"}, {"id": "c", "text": "AWS Site-to-Site VPN"}, {"id": "d", "text": "VPC peering"}]'::jsonb, array['c'], 'A Site-to-Site VPN cria túneis IPsec criptografados pela internet entre o datacenter e a AWS e pode ser configurada rapidamente. O Direct Connect exige um circuito físico.', 'easy', 'Rápido e pela internet.'),
  ('ccp', 'Tecnologia e Serviços', 'Um site com vídeos e imagens tem usuários no mundo inteiro e quer reduzir a latência entregando o conteúdo a partir de locais próximos a eles. Qual serviço usar?', '[{"id": "a", "text": "AWS Direct Connect"}, {"id": "b", "text": "AWS Transit Gateway"}, {"id": "c", "text": "Amazon VPC"}, {"id": "d", "text": "Amazon CloudFront"}]'::jsonb, array['d'], 'O CloudFront é a CDN da AWS: armazena conteúdo em cache nos pontos de presença (edge locations) próximos aos usuários.', 'easy', 'CDN com pontos de presença no mundo todo.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma aplicação TCP não HTTP atende usuários globais e precisa de dois IPs estáticos anycast, roteando o tráfego pela rede da AWS até o endpoint saudável mais próximo. Qual serviço usar?', '[{"id": "a", "text": "Amazon Route 53"}, {"id": "b", "text": "Amazon CloudFront"}, {"id": "c", "text": "AWS Global Accelerator"}, {"id": "d", "text": "Elastic Load Balancing"}]'::jsonb, array['c'], 'O Global Accelerator fornece IPs estáticos anycast e direciona o tráfego pela rede global da AWS, melhorando desempenho e failover para aplicações TCP e UDP. O CloudFront é focado em conteúdo HTTP com cache.', 'hard', 'IPs estáticos anycast e tráfego não HTTP.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa tem 60 VPCs e vários datacenters e quer conectá-los por um hub central, em vez de criar dezenas de conexões ponto a ponto. Qual serviço usar?', '[{"id": "a", "text": "AWS Transit Gateway"}, {"id": "b", "text": "NAT gateway"}, {"id": "c", "text": "VPC peering"}, {"id": "d", "text": "Internet gateway"}]'::jsonb, array['a'], 'O Transit Gateway funciona como um roteador central regional que conecta VPCs e redes locais em topologia hub-and-spoke, simplificando a gestão.', 'hard', 'Hub central em vez de malha.'),
  ('ccp', 'Tecnologia e Serviços', 'Um sistema de pedidos precisa desacoplar o site do processamento de pagamentos, guardando as mensagens até que o processador consiga consumi-las. Qual serviço usar?', '[{"id": "a", "text": "Amazon Simple Queue Service (SQS)"}, {"id": "b", "text": "AWS Direct Connect"}, {"id": "c", "text": "Amazon Route 53"}, {"id": "d", "text": "Amazon EBS"}]'::jsonb, array['a'], 'O SQS é uma fila de mensagens gerenciada: produtores enviam mensagens e consumidores as processam no próprio ritmo, desacoplando os componentes.', 'easy', 'Uma fila guarda o trabalho pendente.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer reagir a eventos de vários serviços AWS e de aplicações SaaS, roteando-os por regras para diferentes destinos. Qual serviço usar?', '[{"id": "a", "text": "Amazon SQS"}, {"id": "b", "text": "Amazon Kinesis Data Streams"}, {"id": "c", "text": "Amazon EventBridge"}, {"id": "d", "text": "AWS Direct Connect"}]'::jsonb, array['c'], 'O EventBridge é um barramento de eventos serverless que recebe eventos de serviços AWS, aplicações próprias e parceiros SaaS e os roteia por regras. Também agenda tarefas.', 'medium', 'Barramento de eventos com regras de roteamento.'),
  ('ccp', 'Tecnologia e Serviços', 'O time quer receber um alerta quando a CPU média de uma instância EC2 passar de 80% por 10 minutos. Qual serviço usar?', '[{"id": "a", "text": "AWS Trusted Advisor"}, {"id": "b", "text": "AWS Artifact"}, {"id": "c", "text": "Amazon CloudWatch (alarme)"}, {"id": "d", "text": "AWS CloudTrail"}]'::jsonb, array['c'], 'Alarmes do CloudWatch observam métricas e disparam ações, como notificações via SNS ou ações de Auto Scaling, quando um limite é ultrapassado.', 'easy', 'Métricas e alarmes.'),
  ('ccp', 'Tecnologia e Serviços', 'Qual painel mostra eventos da AWS que afetam especificamente os recursos da sua conta, como manutenções programadas em instâncias EC2?', '[{"id": "a", "text": "AWS Trusted Advisor"}, {"id": "b", "text": "AWS Health Dashboard"}, {"id": "c", "text": "AWS Config"}, {"id": "d", "text": "AWS Cost Explorer"}]'::jsonb, array['b'], 'O AWS Health Dashboard mostra o status geral dos serviços e uma visão personalizada com eventos e manutenções que impactam os seus recursos.', 'medium', 'Saúde dos serviços AWS que você usa.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma equipe precisa catalogar dados no S3 e criar jobs de ETL serverless para transformá-los antes da análise. Qual serviço usar?', '[{"id": "a", "text": "AWS Glue"}, {"id": "b", "text": "Amazon Kinesis"}, {"id": "c", "text": "Amazon Redshift"}, {"id": "d", "text": "Amazon EMR on EC2"}]'::jsonb, array['a'], 'O Glue oferece um Data Catalog e jobs de ETL serverless em Spark, além de crawlers que descobrem esquemas automaticamente.', 'medium', 'Catálogo de dados e ETL serverless.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer processar grandes volumes de dados com Apache Spark e Hadoop em clusters gerenciados. Qual serviço é indicado?', '[{"id": "a", "text": "AWS Glue DataBrew"}, {"id": "b", "text": "Amazon Lightsail"}, {"id": "c", "text": "Amazon RDS"}, {"id": "d", "text": "Amazon EMR"}]'::jsonb, array['d'], 'O Amazon EMR executa frameworks de big data como Spark, Hadoop, Hive e Presto em clusters gerenciados.', 'medium', 'Big data com frameworks open source.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma loja virtual quer adicionar busca de produtos com relevância e também analisar logs de aplicação quase em tempo real. Qual serviço atende os dois casos?', '[{"id": "a", "text": "Amazon Athena"}, {"id": "b", "text": "AWS Glue"}, {"id": "c", "text": "Amazon Neptune"}, {"id": "d", "text": "Amazon OpenSearch Service"}]'::jsonb, array['d'], 'O OpenSearch Service é usado para busca textual, análise de logs e observabilidade, com painéis no OpenSearch Dashboards.', 'medium', 'Busca e análise de logs.'),
  ('ccp', 'Tecnologia e Serviços', 'Um aplicativo precisa identificar objetos, rostos e textos em fotos enviadas pelos usuários, sem treinar modelos. Qual serviço usar?', '[{"id": "a", "text": "Amazon Rekognition"}, {"id": "b", "text": "Amazon Polly"}, {"id": "c", "text": "Amazon Lex"}, {"id": "d", "text": "Amazon Comprehend"}]'::jsonb, array['a'], 'O Rekognition é um serviço pré-treinado de visão computacional para imagens e vídeos: rótulos, rostos, texto e moderação de conteúdo.', 'easy', 'O dado de entrada é imagem.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer converter textos de notícias em áudio com vozes naturais para um aplicativo de acessibilidade. Qual serviço usar?', '[{"id": "a", "text": "Amazon Textract"}, {"id": "b", "text": "Amazon Polly"}, {"id": "c", "text": "Amazon Transcribe"}, {"id": "d", "text": "Amazon Translate"}]'::jsonb, array['b'], 'O Polly converte texto em fala (text-to-speech) com vozes naturais em vários idiomas, inclusive português.', 'easy', 'Texto entra, voz sai.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma central de atendimento quer transformar as gravações de ligações em texto para análise. Qual serviço faz isso?', '[{"id": "a", "text": "Amazon Polly"}, {"id": "b", "text": "Amazon Lex"}, {"id": "c", "text": "Amazon Rekognition"}, {"id": "d", "text": "Amazon Transcribe"}]'::jsonb, array['d'], 'O Transcribe faz reconhecimento automático de fala (speech-to-text), com suporte a chamadas e identificação de quem está falando.', 'easy', 'Voz entra, texto sai.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer analisar milhares de avaliações de clientes para identificar sentimento e entidades mencionadas. Qual serviço usar?', '[{"id": "a", "text": "Amazon Comprehend"}, {"id": "b", "text": "Amazon Kendra"}, {"id": "c", "text": "Amazon Rekognition"}, {"id": "d", "text": "Amazon Polly"}]'::jsonb, array['a'], 'O Comprehend é um serviço de processamento de linguagem natural que detecta sentimento, entidades, frases-chave e idioma em textos.', 'medium', 'Entender o significado de textos.'),
  ('ccp', 'Tecnologia e Serviços', 'Um banco recebe milhares de formulários digitalizados por dia e precisa extrair campos e tabelas automaticamente. Qual serviço usar?', '[{"id": "a", "text": "Amazon Polly"}, {"id": "b", "text": "Amazon Comprehend"}, {"id": "c", "text": "Amazon Textract"}, {"id": "d", "text": "Amazon Translate"}]'::jsonb, array['c'], 'O Textract vai além do OCR comum: extrai texto, pares chave-valor de formulários e tabelas de documentos digitalizados.', 'medium', 'Extrair dados estruturados de documentos.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma equipe de cientistas de dados quer construir, treinar e implantar modelos próprios de machine learning em uma plataforma gerenciada. Qual serviço usar?', '[{"id": "a", "text": "Amazon Lex"}, {"id": "b", "text": "Amazon SageMaker AI"}, {"id": "c", "text": "Amazon Rekognition"}, {"id": "d", "text": "AWS Glue"}]'::jsonb, array['b'], 'O SageMaker AI cobre todo o ciclo de ML: preparação, treinamento, ajuste, implantação e monitoramento de modelos próprios.', 'medium', 'Modelos próprios exigem uma plataforma completa de ML.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa quer criar uma aplicação de IA generativa usando modelos de fundação de vários fornecedores por uma única API, sem gerenciar infraestrutura. Qual serviço usar?', '[{"id": "a", "text": "Amazon EC2 com GPUs"}, {"id": "b", "text": "Amazon Bedrock"}, {"id": "c", "text": "Amazon Comprehend"}, {"id": "d", "text": "Amazon Textract"}]'::jsonb, array['b'], 'O Bedrock oferece acesso gerenciado a modelos de fundação da Amazon e de outros fornecedores por uma API única, com recursos de customização, agentes e guardrails.', 'medium', 'Modelos de fundação via API gerenciada.'),
  ('ccp', 'Tecnologia e Serviços', 'Qual ferramenta oferece um terminal no navegador, já autenticado e com a AWS CLI instalada, direto do console?', '[{"id": "a", "text": "AWS CloudShell"}, {"id": "b", "text": "AWS Systems Manager Session Manager"}, {"id": "c", "text": "Amazon WorkSpaces"}, {"id": "d", "text": "AWS Cloud9"}]'::jsonb, array['a'], 'O CloudShell é um shell no navegador, autenticado com as credenciais do console e com ferramentas como a AWS CLI pré-instaladas.', 'easy', 'Terminal no próprio console.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma equipe quer automatizar o fluxo de entrega de software: a cada commit, compilar, testar e implantar em produção. Qual serviço orquestra esse pipeline?', '[{"id": "a", "text": "AWS CodePipeline"}, {"id": "b", "text": "Amazon Inspector"}, {"id": "c", "text": "AWS CodeArtifact"}, {"id": "d", "text": "AWS Config"}]'::jsonb, array['a'], 'O CodePipeline orquestra as etapas de CI/CD, integrando-se a repositórios, ao CodeBuild para compilar e testar e ao CodeDeploy ou outros destinos para implantar.', 'medium', 'Pipeline de integração e entrega contínuas.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma equipe front-end quer hospedar e publicar uma aplicação web full-stack com deploy a cada push no Git, autenticação e backend integrados. Qual serviço é indicado?', '[{"id": "a", "text": "Amazon EMR"}, {"id": "b", "text": "AWS Amplify"}, {"id": "c", "text": "AWS Batch"}, {"id": "d", "text": "AWS Outposts"}]'::jsonb, array['b'], 'O Amplify oferece hospedagem com CI/CD a partir do Git e bibliotecas para adicionar autenticação, dados e armazenamento a apps web e mobile.', 'medium', 'Feito para equipes de front-end e mobile.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma fábrica quer conectar milhares de sensores à nuvem de forma segura e rotear as mensagens para outros serviços AWS. Qual serviço usar?', '[{"id": "a", "text": "Amazon Kinesis Video Streams"}, {"id": "b", "text": "Amazon Connect"}, {"id": "c", "text": "AWS Direct Connect"}, {"id": "d", "text": "AWS IoT Core"}]'::jsonb, array['d'], 'O IoT Core conecta dispositivos com MQTT e HTTPS, autentica cada um e roteia mensagens para serviços como Lambda, DynamoDB e S3 por meio de regras.', 'medium', 'Dispositivos e sensores conectados.'),
  ('ccp', 'Tecnologia e Serviços', 'Uma empresa precisa transferir continuamente centenas de terabytes de um NAS local para o Amazon S3 pela rede, com verificação de integridade. Qual serviço usar?', '[{"id": "a", "text": "AWS Backup"}, {"id": "b", "text": "AWS Snowball Edge"}, {"id": "c", "text": "AWS DataSync"}, {"id": "d", "text": "Amazon CloudFront"}]'::jsonb, array['c'], 'O DataSync automatiza e acelera transferências online entre armazenamento local e serviços AWS, com agendamento, criptografia e validação de integridade.', 'medium', 'Transferência online, não por dispositivo físico.'),
  ('ccp', 'Tecnologia e Serviços', 'Quais serviços são considerados serverless, sem servidores para o cliente provisionar ou gerenciar? (Escolha DUAS)', '[{"id": "a", "text": "Amazon Lightsail"}, {"id": "b", "text": "AWS Outposts"}, {"id": "c", "text": "AWS Lambda"}, {"id": "d", "text": "AWS Fargate"}, {"id": "e", "text": "Amazon EC2"}]'::jsonb, array['c', 'd'], 'Lambda e Fargate abstraem totalmente os servidores: você entrega código ou contêiner e paga pelo uso. EC2 e Lightsail são servidores virtuais que você administra, e Outposts é hardware AWS no seu datacenter.', 'medium', 'Elimine as opções em que você escolhe e administra um servidor.'),
  ('ccp', 'Tecnologia e Serviços', 'Quais serviços oferecem bancos de dados relacionais gerenciados? (Escolha DUAS)', '[{"id": "a", "text": "Amazon RDS"}, {"id": "b", "text": "Amazon DynamoDB"}, {"id": "c", "text": "Amazon ElastiCache"}, {"id": "d", "text": "Amazon Neptune"}, {"id": "e", "text": "Amazon Aurora"}]'::jsonb, array['a', 'e'], 'RDS e Aurora são bancos relacionais com SQL e esquemas. DynamoDB é chave-valor e documentos, Neptune é grafo e ElastiCache é cache em memória.', 'medium', 'Relacional = tabelas, SQL e esquemas.'),
  ('ccp', 'Tecnologia e Serviços', 'Quais formas permitem acessar os serviços AWS programaticamente, por scripts ou código? (Escolha DUAS)', '[{"id": "a", "text": "AWS Trusted Advisor"}, {"id": "b", "text": "AWS Marketplace"}, {"id": "c", "text": "AWS Command Line Interface (CLI)"}, {"id": "d", "text": "AWS SDKs"}, {"id": "e", "text": "AWS Artifact"}]'::jsonb, array['c', 'd'], 'A CLI e os SDKs chamam as APIs da AWS a partir de scripts e aplicações. Artifact, Trusted Advisor e Marketplace são serviços, não formas de acesso programático.', 'easy', 'Pense em ferramentas para desenvolvedores.'),
  ('ccp', 'Tecnologia e Serviços', 'Quais serviços ajudam a desacoplar componentes de uma aplicação por meio de mensagens? (Escolha DUAS)', '[{"id": "a", "text": "Amazon Route 53"}, {"id": "b", "text": "AWS Direct Connect"}, {"id": "c", "text": "Amazon SQS"}, {"id": "d", "text": "Amazon SNS"}, {"id": "e", "text": "Amazon EBS"}]'::jsonb, array['c', 'd'], 'O SQS (filas) e o SNS (publicação e assinatura) permitem que componentes se comuniquem de forma assíncrona, sem depender diretamente uns dos outros.', 'medium', 'Procure os serviços de mensageria.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma aplicação nova tem uso imprevisível e de curta duração, e a equipe não quer nenhum compromisso de longo prazo. Qual opção de compra do EC2 usar?', '[{"id": "a", "text": "Savings Plans de 1 ano"}, {"id": "b", "text": "Dedicated Hosts com reserva"}, {"id": "c", "text": "Sob demanda (On-Demand)"}, {"id": "d", "text": "Instâncias Reservadas de 3 anos"}]'::jsonb, array['c'], 'Instâncias sob demanda são cobradas por segundo ou hora de uso, sem compromisso nem pagamento antecipado, ideais para cargas imprevisíveis ou testes.', 'easy', 'Sem compromisso é a palavra-chave.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma empresa roda cargas em EC2, Fargate e Lambda, muda tipos de instância e Regiões com frequência e quer desconto com compromisso de gasto por hora. Qual opção oferece essa flexibilidade?', '[{"id": "a", "text": "Instâncias Reservadas Standard"}, {"id": "b", "text": "Compute Savings Plans"}, {"id": "c", "text": "Instâncias Spot"}, {"id": "d", "text": "EC2 Instance Savings Plans"}]'::jsonb, array['b'], 'O Compute Savings Plans aplica o desconto a EC2 de qualquer família, tamanho e Região, além de Fargate e Lambda, em troca de um compromisso de gasto por hora por 1 ou 3 anos.', 'medium', 'A flexibilidade cobre mais de um serviço de computação.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Um banco de dados roda 24 horas por dia em uma instância fixa e continuará assim pelos próximos 3 anos. Qual opção gera a maior economia em relação ao sob demanda?', '[{"id": "a", "text": "Instância sob demanda"}, {"id": "b", "text": "Instância Reservada ou Savings Plan de 3 anos com pagamento antecipado total"}, {"id": "c", "text": "Instância Reservada de 1 ano sem pagamento antecipado"}, {"id": "d", "text": "Instância Spot"}]'::jsonb, array['b'], 'Quanto maior o prazo e o pagamento antecipado, maior o desconto. Spot não serve para um banco que não pode ser interrompido.', 'medium', 'Uso constante e previsível combina com compromisso longo.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma empresa tem licenças de software cobradas por soquete e por núcleo físico e quer reutilizá-las na AWS cumprindo os termos de licenciamento. Qual opção EC2 é a mais indicada?', '[{"id": "a", "text": "AWS Lambda"}, {"id": "b", "text": "Instâncias sob demanda em hardware compartilhado"}, {"id": "c", "text": "Dedicated Hosts"}, {"id": "d", "text": "Instâncias Spot"}]'::jsonb, array['c'], 'Dedicated Hosts dão visibilidade e controle sobre soquetes e núcleos físicos de um servidor dedicado, o que permite usar licenças BYOL vinculadas ao hardware.', 'hard', 'A licença depende do hardware físico.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Antes de migrar, uma empresa quer estimar quanto vai custar por mês uma arquitetura com EC2, RDS e S3. Qual ferramenta usar?', '[{"id": "a", "text": "AWS Budgets"}, {"id": "b", "text": "AWS Cost and Usage Report"}, {"id": "c", "text": "AWS Cost Explorer"}, {"id": "d", "text": "AWS Pricing Calculator"}]'::jsonb, array['d'], 'O Pricing Calculator estima custos de arquiteturas que ainda não existem. Cost Explorer, Budgets e CUR trabalham com o uso real da conta.', 'easy', 'A arquitetura ainda não foi criada.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'O time de FinOps precisa do nível mais detalhado de dados de cobrança, hora a hora e por recurso, para carregar em ferramentas de BI. Qual recurso fornece isso?', '[{"id": "a", "text": "AWS Health Dashboard"}, {"id": "b", "text": "Painel de faturas mensais em PDF"}, {"id": "c", "text": "AWS Cost and Usage Report (CUR)"}, {"id": "d", "text": "AWS Pricing Calculator"}]'::jsonb, array['c'], 'O CUR entrega os dados de custo e uso mais granulares da AWS em arquivos no S3, que podem ser consultados com Athena ou ferramentas de BI.', 'medium', 'É o relatório mais granular disponível.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma empresa quer ser avisada automaticamente quando surgir um gasto fora do padrão, como um serviço que dobrou de custo de um dia para o outro, sem definir limites manualmente. Qual recurso usar?', '[{"id": "a", "text": "AWS Artifact"}, {"id": "b", "text": "Service Quotas"}, {"id": "c", "text": "AWS Cost Anomaly Detection"}, {"id": "d", "text": "AWS Pricing Calculator"}]'::jsonb, array['c'], 'O Cost Anomaly Detection usa machine learning para aprender o padrão de gastos e alertar sobre anomalias, sem que você precise definir valores fixos.', 'medium', 'Detecta o que foge do padrão, sem limite manual.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma equipe suspeita que muitas instâncias EC2 estão superdimensionadas. Qual serviço recomenda tipos e tamanhos mais adequados com base no uso real?', '[{"id": "a", "text": "AWS Budgets"}, {"id": "b", "text": "AWS Artifact"}, {"id": "c", "text": "AWS Pricing Calculator"}, {"id": "d", "text": "AWS Compute Optimizer"}]'::jsonb, array['d'], 'O Compute Optimizer analisa métricas de uso e recomenda o dimensionamento correto de EC2, Auto Scaling, EBS, Lambda e outros recursos.', 'medium', 'Dimensionamento correto com base em métricas.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Como o AWS Lambda é cobrado?', '[{"id": "a", "text": "Por um valor fixo mensal por função"}, {"id": "b", "text": "Por hora, enquanto a função estiver implantada"}, {"id": "c", "text": "Somente pela quantidade de código armazenado"}, {"id": "d", "text": "Pelo número de requisições e pela duração da execução, proporcional à memória configurada"}]'::jsonb, array['d'], 'O Lambda cobra por requisição e por duração (em GB-segundo, conforme a memória alocada). Se a função não executa, não há cobrança por computação.', 'medium', 'Você paga quando o código roda.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Quais fatores influenciam diretamente o custo do Amazon S3? (Escolha DUAS)', '[{"id": "a", "text": "Número de requisições e transferência de dados para fora da AWS"}, {"id": "b", "text": "Quantidade de dados armazenados e a classe de armazenamento"}, {"id": "c", "text": "Quantidade de usuários IAM da conta"}, {"id": "d", "text": "Quantidade de buckets criados"}, {"id": "e", "text": "Número de Zonas de Disponibilidade da Região"}]'::jsonb, array['a', 'b'], 'O S3 cobra por armazenamento (volume e classe), requisições, recuperação em algumas classes e transferência de dados para fora. Usuários IAM e número de AZs não entram na conta.', 'medium', 'Pense no que você armazena e no que você acessa.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Qual tipo de transferência de dados normalmente gera cobrança?', '[{"id": "a", "text": "Upload de arquivos da internet para o S3"}, {"id": "b", "text": "Dados enviados de uma Região AWS para outra Região"}, {"id": "c", "text": "Dados recebidos da internet para dentro da AWS"}, {"id": "d", "text": "Tráfego entre EC2 e S3 na mesma Região"}]'::jsonb, array['b'], 'A entrada de dados na AWS é gratuita e o tráfego entre EC2 e S3 na mesma Região também. Transferências entre Regiões e para a internet são cobradas.', 'medium', 'Dados saindo de uma Região costumam custar.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Um desenvolvedor tem uma dúvida técnica e quer pesquisar respostas da comunidade e de especialistas da AWS, sem abrir um chamado de suporte. Qual recurso usar?', '[{"id": "a", "text": "AWS Marketplace"}, {"id": "b", "text": "AWS re:Post"}, {"id": "c", "text": "AWS Cost Explorer"}, {"id": "d", "text": "AWS Artifact"}]'::jsonb, array['b'], 'O AWS re:Post é a comunidade de perguntas e respostas da AWS, com respostas da comunidade e de especialistas, além de artigos do Knowledge Center.', 'easy', 'É uma comunidade de perguntas e respostas.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma empresa quer contratar uma consultoria especializada e validada pela AWS para conduzir a migração. Onde encontrar esse tipo de empresa?', '[{"id": "a", "text": "No Amazon Connect"}, {"id": "b", "text": "No AWS Artifact"}, {"id": "c", "text": "Na rede de parceiros da AWS (AWS Partner Network)"}, {"id": "d", "text": "No AWS Trusted Advisor"}]'::jsonb, array['c'], 'A AWS Partner Network reúne consultorias e fornecedores de software validados, com competências em áreas como migração, segurança e dados.', 'easy', 'Procure parceiros, não serviços.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Uma aplicação não consegue lançar mais instâncias porque atingiu o limite da conta para aquele tipo de instância. Onde verificar e solicitar o aumento desse limite?', '[{"id": "a", "text": "AWS Budgets"}, {"id": "b", "text": "AWS Artifact"}, {"id": "c", "text": "AWS Cost Explorer"}, {"id": "d", "text": "Service Quotas"}]'::jsonb, array['d'], 'O Service Quotas mostra os limites (cotas) de cada serviço por Região e permite solicitar aumentos diretamente.', 'medium', 'Limites de serviço são cotas.'),
  ('ccp', 'Cobrança, Preços e Suporte', 'Qual princípio faz parte do modelo de preços da AWS?', '[{"id": "a", "text": "Pagar uma licença anual fixa independentemente do uso"}, {"id": "b", "text": "Pagar o mesmo valor por hora em qualquer Região e serviço"}, {"id": "c", "text": "Pagar pelo que usar, com descontos por compromisso e preços menores por unidade em volumes maiores"}, {"id": "d", "text": "Pagar antecipadamente por toda a capacidade de pico"}]'::jsonb, array['c'], 'O modelo da AWS combina pagamento por uso, economia ao se comprometer (Savings Plans e reservas) e preços menores por unidade conforme o volume cresce.', 'easy', 'Pense em como o custo acompanha o uso.'),
  ('ccp', 'Conceitos de Nuvem', 'Uma empresa desativou a sala de servidores e realocou a equipe que trocava discos e cuidava de energia e refrigeração para o desenvolvimento de produtos. Qual benefício da nuvem isso ilustra?', '[{"id": "a", "text": "Garantir disponibilidade de 100% das aplicações"}, {"id": "b", "text": "Trocar despesas variáveis por despesas de capital"}, {"id": "c", "text": "Aumentar a velocidade e a agilidade de lançamentos"}, {"id": "d", "text": "Parar de gastar dinheiro operando e mantendo datacenters"}]'::jsonb, array['d'], 'Na nuvem, a AWS cuida do trabalho pesado indiferenciado da infraestrutura física, e a empresa concentra pessoas e investimento no que diferencia o negócio.', 'easy', 'O foco é o trabalho com a infraestrutura física.');
